import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageStudents() {
  const [students, setStudents] = useState([]);
  const [formData, setFormData] = useState({
    name: '', grade: 'Grade 10', subjects: '', phone_number: '', parent_phone: '', address: '', password: 'ST@123'
  });

  const fetchStudents = () => {
    axios.get('http://localhost:8081/api/view-students')
      .then(res => setStudents(res.data))
      .catch(err => console.error(err));
  };

  useEffect(() => { fetchStudents(); }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    axios.post('http://localhost:8081/api/add-student', formData)
      .then(res => {
        if(res.data.status === "Success") {
            fetchStudents(); 
            setFormData({ name: '', grade: 'Grade 10', subjects: '', phone_number: '', parent_phone: '', address: '', password: 'ST@123' });
            alert("✅ Student added successfully!");
        } else {
            alert("❌ Failed to add student.");
        }
      });
  };

  return (
    <div style={{ padding: '30px', backgroundColor: '#f8fafc', minHeight: '100vh' }}>
      <h2 style={{ color: '#15803d', marginBottom: '20px' }}>Manage Students</h2>
      
      {/* 🟢 Add New Student Form */}
      <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '12px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)', marginBottom: '30px' }}>
        <h3 style={{ marginTop: 0, color: '#334155', borderBottom: '2px solid #f1f5f9', paddingBottom: '10px' }}>Add New Student</h3>
        <form onSubmit={handleSubmit} style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px', marginTop: '20px' }}>
          
          <input type="text" placeholder="Full Name" value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} required style={inputStyle} />
          
          <select value={formData.grade} onChange={(e) => setFormData({...formData, grade: e.target.value})} style={inputStyle}>
            {['Grade 06', 'Grade 07', 'Grade 08', 'Grade 09', 'Grade 10', 'Grade 11', 'A/L 2026', 'A/L 2027'].map(g => <option key={g} value={g}>{g}</option>)}
          </select>

          <input type="text" placeholder="Subjects (e.g. Maths, Science)" value={formData.subjects} onChange={(e) => setFormData({...formData, subjects: e.target.value})} style={inputStyle} />
          <input type="text" placeholder="Student Phone Number" value={formData.phone_number} onChange={(e) => setFormData({...formData, phone_number: e.target.value})} style={inputStyle} />
          <input type="text" placeholder="Parent Phone Number" value={formData.parent_phone} onChange={(e) => setFormData({...formData, parent_phone: e.target.value})} style={inputStyle} />
          <input type="text" placeholder="Address" value={formData.address} onChange={(e) => setFormData({...formData, address: e.target.value})} style={inputStyle} />
          
          <div style={{ gridColumn: 'span 2', backgroundColor: '#f0fdf4', padding: '10px', borderRadius: '8px', border: '1px dashed #22c55e', fontSize: '13px', color: '#15803d' }}>
            <strong>Note:</strong> The default password for this student will be set to <b>ST@123</b>. They can change it after logging in.
          </div>

          <button type="submit" style={{ gridColumn: 'span 2', padding: '14px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '15px' }}>
            + Register Student
          </button>
        </form>
      </div>

      {/* 🟢 View Students Table */}
      <div style={{ backgroundColor: 'white', borderRadius: '12px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)', overflow: 'auto' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', minWidth: '800px' }}>
          <thead style={{ backgroundColor: '#15803d', color: 'white' }}>
            <tr>
              <th style={thStyle}>Name</th><th style={thStyle}>Grade</th><th style={thStyle}>Subjects</th>
              <th style={thStyle}>Student Phone</th><th style={thStyle}>Parent Phone</th><th style={thStyle}>Address</th>
            </tr>
          </thead>
          <tbody>
            {students.length > 0 ? students.map((student) => (
              <tr key={student.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
                <td style={tdStyle}><b>{student.name}</b></td><td style={tdStyle}>{student.grade}</td>
                <td style={tdStyle}>{student.subjects}</td><td style={tdStyle}>{student.phone_number || '-'}</td>
                <td style={tdStyle}>{student.parent_phone || '-'}</td><td style={tdStyle}>{student.address || '-'}</td>
              </tr>
            )) : (
              <tr><td colSpan="6" style={{ padding: '20px', textAlign: 'center', color: '#ef4444' }}>No students found.</td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

const inputStyle = { padding: '12px', border: '1px solid #cbd5e1', borderRadius: '8px', outline: 'none', width: '100%', boxSizing: 'border-box' };
const thStyle = { padding: '15px', fontSize: '14px', whiteSpace: 'nowrap' };
const tdStyle = { padding: '15px', fontSize: '14px', color: '#475569' };
